export const card = { id: "knights", type: "play", title: P("Le tour du cavalier", "The knight’s tour"), topic: P("Graphes", "Graph theory"), difficulty: 2, minutes: 15, extension: P("Compare les échiquiers pairs et impairs. Un parcours peut-il revenir à son départ ?", "Compare even and odd boards. Can a tour return to its start?") };
export const variant = {
  params: [int("n", "Côté de l’échiquier", "Board side", 3, 10, 8)],
  answer: ({ n }) => n * n - 1,
  prompt: ({ n }) => P(`Sur un échiquier ${n} × ${n}, essaie de visiter chaque case exactement une fois avec un cavalier. Si un parcours ouvert existe, combien de déplacements comporte-t-il ? Ne compte pas la case de départ comme un déplacement.`, `On a ${n} × ${n} board, try to visit every square exactly once with a knight. If an open tour exists, how many moves does it contain? Do not count the starting square as a move.`),
  solution: ({ n }) => P(`Il y a ${n * n} cases. La première est occupée dès le départ, avant tout déplacement ; chaque déplacement amène le cavalier sur une nouvelle case. Un parcours ouvert qui passe par toutes les cases compte donc ${n * n - 1} déplacements ; un circuit fermé, qui revient à son point de départ, en compte ${n * n}. Ce calcul ne prouve pas qu’un tel parcours existe : il dit seulement combien de coups il aurait. Pour un circuit fermé, colorie l’échiquier en noir et blanc : chaque coup du cavalier change de couleur. Un circuit alterne donc blanc et noir et passe par autant de cases de chaque couleur. Si le côté est impair, son carré est un nombre impair de cases, ce qui est impossible. Quand le côté est pair, ce raisonnement n’exclut rien, et il ne dit rien des parcours ouverts.`, `There are ${n * n} squares. The first one is occupied from the start, before any move; every move takes the knight to a new square. An open tour through all the squares therefore has ${n * n - 1} moves; a closed tour, which comes back to its starting point, has ${n * n}. This count does not prove that such a tour exists: it only says how many moves it would have. For a closed tour, colour the board black and white: every knight move changes colour. A closed tour therefore alternates white and black and visits as many squares of each colour. If the side is odd, the number of squares (its square) is an odd number of squares, which is impossible. When the side is even, this argument rules nothing out, and it says nothing about open tours.`),
};
export const original = ({ n }) => P(`Peux-tu visiter chaque case d’un échiquier ${n} × ${n} exactement une fois par des coups de cavalier ? Cherche un parcours ouvert, puis un parcours fermé. Quels obstacles peux-tu démontrer ?`, `Can you visit every square of a ${n} × ${n} board exactly once using knight moves? Seek an open tour, then a closed tour. Which obstructions can you prove?`);
